/* From Uiverse.io by lenin55 - Tags: material design, loader */
/* //codelessly loader style */
.__UIV_SCOPE__ .ui-loader {
  display: inline-block;
  width: 50px;
  height: 50px;
}

.__UIV_SCOPE__ .loader-blk {
  color: #3f51b5;
  animation: rotate-outer08 1.4s linear infinite;
}

.__UIV_SCOPE__ .multiColor-loader {
  display: block;
  animation: color-anim08 1.4s infinite;
}

.__UIV_SCOPE__ .loader-circle {
  stroke: currentColor;
}

.__UIV_SCOPE__ .MuiCircularProgress-circleStatic {
  transition: stroke-dashoffset 0.3s cubic-bezier(0.4, 0, 0.2, 1) 0s;
}

.__UIV_SCOPE__ .loader-circle-animation {
  animation: rotate-inner08 1.4s ease-in-out
    infinite;
  stroke-dasharray: 80px, 200px;
  stroke-dashoffset: 0;
}

@keyframes rotate-outer08 {
  0% {
    transform-origin: 50% 50%;
  }

  100% {
    transform: rotate(360deg);
  }
}

@keyframes rotate-inner08 {
  0% {
    stroke-dasharray: 1px, 200px;
    stroke-dashoffset: 0;
  }

  50% {
    stroke-dasharray: 100px, 200px;
    stroke-dashoffset: -15px;
  }

  100% {
    stroke-dasharray: 100px, 200px;
    stroke-dashoffset: -125px;
  }
}

@keyframes color-anim08 {
  0% {
    color: #4285f4;
  }

  25% {
    color: #ea4335;
  }

  50% {
    color: #f9bb2d;
  }

  75% {
    color: #34a853;
  }
}
